    return 0;
}

problems.solutionCode:
#include <stdio.h>

int maxSubArray(int a[], int n) {
    int best = a[0], cur = a[0];
    for (int i = 1; i < n; i++) {
        cur = cur + a[i] > a[i] ? cur + a[i] : a[i];
        if (cur > best) best = cur;
    }
    return best;
}

